package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.strategy.api.model.StrategySignal;import java.math.BigDecimal;import java.time.Instant;import org.junit.jupiter.api.Test;
class ExecutionStateMachineTest{@Test void enforcesOneLongAndTreatsInvalidTransitionsAsNoOps(){ExecutionStateMachine state=new ExecutionStateMachine();state.decide(StrategySignal.SELL);assertFalse(state.mayClose());state.decide(StrategySignal.BUY);assertTrue(state.mayOpen());Position p=new Position(Instant.EPOCH,Money.of(BigDecimal.TEN),new Quantity(BigDecimal.ONE),Money.zero(),Money.of(BigDecimal.TEN));state.opened(p);state.decide(StrategySignal.BUY);assertFalse(state.mayOpen());assertSame(p,state.position());state.decide(StrategySignal.SELL);assertTrue(state.mayClose());assertSame(p,state.closed());assertNull(state.position());state.decide(StrategySignal.HOLD);assertFalse(state.mayOpen());}}
